def gen(rng):
    def rs(n, lo=33, hi=126):
        return ''.join(chr(rng.randint(lo, hi)) for _ in range(n))

    tests = ['a', 'ab', 'hello', 'Madam1', 'racecar', 'z' * 7, '12345', '!@#$%^&*()', 'aAbBcC']
    for n in range(1, 16):
        tests.append(rs(n))
    for _ in range(5):
        tests.append(rs(rng.randint(20, 300), 97, 122))
    N = 100000
    tests.append(rs(N))
    tests.append('a' * N)
    tests.append('ab' * (N // 2))
    tests.append(rs(N, 48, 57))
    return tests

